insert into public.products (id,name,slug,description,category_id,price_kobo,currency,availability,status,is_featured,seo_title,seo_description) values ('d0000000-0000-4000-8000-000000000001','Aurelia Decorative Vase','aurelia-decorative-vase','A sculptural ceramic vase with a softly fluted body and a matte ivory glaze. The Aurelia is designed to hold its own on a console or shelf, and looks just as considered empty as it does with a single stem. Each piece is finished by hand, so subtle variation in tone and texture is expected and part of its character.','c0000000-0000-4000-8000-000000000001',1850000,'NGN','available'::public.availability_status,'published'::public.publication_status,true,'Aurelia Decorative Vase — Fluted Ivory Ceramic','A fluted ceramic decorative vase in warm matte ivory. A sculptural accent for consoles, shelves and sideboards.') on conflict (slug) do update set name = excluded.name, description = excluded.description, category_id = excluded.category_id, price_kobo = excluded.price_kobo, availability = excluded.availability, status = excluded.status, is_featured = excluded.is_featured, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.products (id,name,slug,description,category_id,price_kobo,currency,availability,status,is_featured,seo_title,seo_description) values ('d0000000-0000-4000-8000-000000000002','Essential Oversized T-Shirt','essential-oversized-t-shirt','The everyday tee, refined. A heavyweight cotton jersey with a boxy, oversized cut, dropped shoulders and a clean hem. The Ecru colourway is garment-dyed for a soft, lived-in hand from the first wear. Style it loose over denim or tuck it into tailoring.','c0000000-0000-4000-8000-000000000002',1200000,'NGN','available'::public.availability_status,'published'::public.publication_status,true,'Essential Oversized T-Shirt — Ecru Heavyweight Cotton','A heavyweight cotton oversized t-shirt in soft ecru with dropped shoulders and a relaxed, boxy fit.') on conflict (slug) do update set name = excluded.name, description = excluded.description, category_id = excluded.category_id, price_kobo = excluded.price_kobo, availability = excluded.availability, status = excluded.status, is_featured = excluded.is_featured, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.products (id,name,slug,description,category_id,price_kobo,currency,availability,status,is_featured,seo_title,seo_description) values ('d0000000-0000-4000-8000-000000000003','Minimalist Tattoo Sticker Set','minimalist-tattoo-sticker-set','A curated sheet of fine-line temporary tattoos — botanical stems, small geometric marks and delicate script-free linework. Each design is easy to apply with water and typically lasts a few days on skin. A low-commitment way to try a placement before you commit.','c0000000-0000-4000-8000-000000000003',350000,'NGN','available'::public.availability_status,'published'::public.publication_status,false,'Minimalist Tattoo Sticker Set — Fine-Line Temporary Tattoos','A sheet of fine-line minimalist temporary tattoos in black ink. Easy to apply and remove.') on conflict (slug) do update set name = excluded.name, description = excluded.description, category_id = excluded.category_id, price_kobo = excluded.price_kobo, availability = excluded.availability, status = excluded.status, is_featured = excluded.is_featured, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.products (id,name,slug,description,category_id,price_kobo,currency,availability,status,is_featured,seo_title,seo_description) values ('d0000000-0000-4000-8000-000000000004','Signature Waist Bead Set','signature-waist-bead-set','A hand-strung strand of small polished glass beads in burgundy, champagne gold and ivory, finished with a fine gold-tone clasp and adjustable chain. Wear it alone or layer with one of our other strands. Strung to order, so allow a little time before dispatch.','c0000000-0000-4000-8000-000000000004',500000,'NGN','made_to_order'::public.availability_status,'published'::public.publication_status,true,'Signature Waist Bead Set — Burgundy & Champagne','Hand-strung waist beads in burgundy, champagne gold and ivory with an adjustable gold-tone closure.') on conflict (slug) do update set name = excluded.name, description = excluded.description, category_id = excluded.category_id, price_kobo = excluded.price_kobo, availability = excluded.availability, status = excluded.status, is_featured = excluded.is_featured, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.products (id,name,slug,description,category_id,price_kobo,currency,availability,status,is_featured,seo_title,seo_description) values ('d0000000-0000-4000-8000-000000000005','Modern Kitchen Utensil Set','modern-kitchen-utensil-set','A four-piece cooking set — ladle, slotted turner, serving spoon and whisk — with matte black heads and balanced handles. Heat-resistant and comfortable to hold, with a silhouette clean enough to leave on the counter. Hand wash to preserve the finish.','c0000000-0000-4000-8000-000000000005',1500000,'NGN','available'::public.availability_status,'published'::public.publication_status,false,'Modern Kitchen Utensil Set — Matte Black, 4 Pieces','A modern four-piece kitchen utensil set with matte black heads and balanced handles.') on conflict (slug) do update set name = excluded.name, description = excluded.description, category_id = excluded.category_id, price_kobo = excluded.price_kobo, availability = excluded.availability, status = excluded.status, is_featured = excluded.is_featured, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.products (id,name,slug,description,category_id,price_kobo,currency,availability,status,is_featured,seo_title,seo_description) values ('d0000000-0000-4000-8000-000000000006','Everyday Comfort Slides','everyday-comfort-slides','A padded slide in soft sand beige, built for the days that do not slow down. The wide strap is lined for comfort and the sole has just enough grip for everyday wear. Water-resistant and easy to wipe clean.','c0000000-0000-4000-8000-000000000006',1650000,'NGN','available'::public.availability_status,'published'::public.publication_status,true,'Everyday Comfort Slides — Sand Beige Padded Slides','Padded everyday slides in sand beige with a comfortable wide strap and grippy sole.') on conflict (slug) do update set name = excluded.name, description = excluded.description, category_id = excluded.category_id, price_kobo = excluded.price_kobo, availability = excluded.availability, status = excluded.status, is_featured = excluded.is_featured, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.products (id,name,slug,description,category_id,price_kobo,currency,availability,status,is_featured,seo_title,seo_description) values ('d0000000-0000-4000-8000-000000000007','Everyday Luxe Shoulder Bag','everyday-luxe-shoulder-bag','A structured shoulder bag in deep burgundy with a slim champagne gold-tone clasp and a short strap that sits neatly under the arm. Lined interior with a single slip pocket — room for a phone, cardholder, keys and a small pouch. A considered everyday bag that dresses up as easily as it dresses down.','c0000000-0000-4000-8000-000000000007',2200000,'NGN','available'::public.availability_status,'published'::public.publication_status,true,'Everyday Luxe Shoulder Bag — Burgundy Structured Bag','A structured burgundy shoulder bag with a champagne gold-tone clasp and a compact, elegant silhouette.') on conflict (slug) do update set name = excluded.name, description = excluded.description, category_id = excluded.category_id, price_kobo = excluded.price_kobo, availability = excluded.availability, status = excluded.status, is_featured = excluded.is_featured, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.products (id,name,slug,description,category_id,price_kobo,currency,availability,status,is_featured,seo_title,seo_description) values ('d0000000-0000-4000-8000-000000000008','Classic Gold-Tone Jewelry Set','classic-gold-tone-jewelry-set','A fine gold-tone chain necklace with matching small hoop earrings. Lightweight enough for all-day wear and simple enough to layer with pieces you already own. Keep away from perfume and water, and store in the pouch provided.','c0000000-0000-4000-8000-000000000008',850000,'NGN','available'::public.availability_status,'published'::public.publication_status,false,'Classic Gold-Tone Jewelry Set — Necklace & Hoops','A classic gold-tone jewellery set with a fine chain necklace and matching small hoop earrings.') on conflict (slug) do update set name = excluded.name, description = excluded.description, category_id = excluded.category_id, price_kobo = excluded.price_kobo, availability = excluded.availability, status = excluded.status, is_featured = excluded.is_featured, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
