insert into public.announcements (id,message,is_enabled) values ('a0000000-0000-4000-8000-000000000001','Welcome to Corazon Empire — curated pieces for the wardrobe and the home. Confirm availability and delivery on WhatsApp or by email.',true) on conflict (id) do update set message = excluded.message, is_enabled = excluded.is_enabled;
